import sys
p=sys.argv[1]; s=open(p).read()
comp='''/** Void the selected claims together with the reason chosen in the bar (offered while the sheet has void reasons):
 *  the server voids, in list order and by the rules of a single void, each that can be voided and leaves the rest;
